(function(){document.addEventListener("DOMContentLoaded",function(){var t=2e3,e=document.querySelectorAll(".share-copy");if(!e.length)return;e.forEach(function(e){e.addEventListener("click",function(){var n=e.getAttribute("data-url");if(!n)return;if(!navigator.clipboard||!navigator.clipboard.writeText)return;navigator.clipboard.writeText(n).then(function(){e.classList.add("copied"),setTimeout(function(){e.classList.remove("copied")},t)}).catch(function(e){console.warn("Share copy failed:",e)})})})})})()